// TestAuthLimiterOnBlockCallback verifies that the SetOnBlock callback is
// invoked exactly once when the burst threshold is crossed (issue #831).
func TestAuthLimiterOnBlockCallback(t *testing.T) {
	resolver := ratelimit.NewClientIPResolver(nil)
	al := ratelimit.NewAuthLimiter(60, 3, 5*time.Minute, resolver)

	calls := 0
	al.SetOnBlock(func() { calls++ })

	clientIP := "198.51.100.5"
	for i := 0; i < 3; i++ {
		al.RecordFailure(clientIP)
	}

	if calls != 1 {
		t.Errorf("onBlock callback calls = %d, want 1", calls)
	}

	al.RecordFailure(clientIP)
	if calls != 1 {
		t.Errorf("onBlock callback calls after second RecordFailure past threshold = %d, want 1", calls)
	}

	al2 := ratelimit.NewAuthLimiter(60, 2, 5*time.Minute, resolver)
	calls2 := 0
	al2.SetOnBlock(func() { calls2++ })
	al2.RecordFailure(clientIP)
	if calls2 != 0 {
		t.Errorf("onBlock callback calls before threshold = %d, want 0", calls2)
	}
	al2.RecordFailure(clientIP)
	if calls2 != 1 {
		t.Errorf("onBlock callback calls after reaching burst=2 = %d, want 1", calls2)
	}
}

// TestAuthLimiterBlockedCallbackNotCalledOnAlreadyBlocked verifies that the
// onBlock callback fires only on the transition to blocked, not on subsequent
// RecordFailure calls for an already-blocked IP (issue #831).
func TestAuthLimiterBlockedCallbackNotCalledOnAlreadyBlocked(t *testing.T) {
	resolver := ratelimit.NewClientIPResolver(nil)
	al := ratelimit.NewAuthLimiter(60, 2, 5*time.Minute, resolver)

	calls := 0
	al.SetOnBlock(func() { calls++ })

	ip := "203.0.2.1"
	al.RecordFailure(ip)
	al.RecordFailure(ip)

	if calls != 1 {
		t.Fatalf("onBlock calls after threshold = %d, want 1", calls)
	}

	for i := 0; i < 5; i++ {
		al.RecordFailure(ip)
	}
	if calls != 1 {
		t.Errorf("onBlock calls after 5 more failures (already blocked) = %d, want 1", calls)
	}
}

